test('onIdle accepts an abort signal and rejects only the aborted waiter', async t => {
	const limit = pLimit(1);

	limit(() => delay(50));

	const controller = new AbortController();
	const aborted = limit.onIdle({signal: controller.signal});
	const other = limit.onIdle();

	const error = abortError();
	controller.abort(error);

	await t.throwsAsync(aborted, {is: error});

	// The other waiter must still resolve once the limiter is idle.
