	controller.abort(reason);

	await t.throwsAsync(waiter, {is: reason});
});

test('aborting onIdle does not cancel jobs', async t => {
	const limit = pLimit(1);
	const completed = [];

	const job = limit(async () => {
		await delay(20);
		completed.push('job');
		return 'done';
	});

	const controller = new AbortController();
	const waiter = limit.onIdle({signal: controller.signal});

	controller.abort(abortError());
	await t.throwsAsync(waiter);

	// The job keeps running and completes normally.
	t.is(await job, 'done');
	t.deepEqual(completed, ['job']);
	t.is(limit.activeCount, 0);
});

