import process from 'node:process';
import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle resolves after all queued jobs finish', async t => {
	const limit = pLimit(2);
	const order = [];

	const promises = Array.from({length: 6}, (_, index) => limit(async () => {
		await delay(10);
		order.push(index);
		return index;
	}));

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	t.deepEqual(order, [0, 1, 2, 3, 4, 5]);
	await Promise.all(promises);
});

test('onIdle resolves after jobs that reject', async t => {
	const limit = pLimit(2);
	const error = new Error('🦄');

	const promises = [
		limit(async () => {
			await delay(10);
			throw error;
		}),
		limit(async () => {
			await delay(20);
			return 'ok';
		}),
		limit(async () => {
			await delay(5);
			throw error;
		}),
	];

	// Observe rejections so they are not unhandled.
	for (const promise of promises) {
		promise.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
	}

	await t.notThrowsAsync(limit.onIdle());

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle supports multiple concurrent waiters', async t => {
	const limit = pLimit(1);

	let ran = false;
	limit(async () => {
		await delay(20);
		ran = true;
	});

	const first = limit.onIdle();
	const second = limit.onIdle();
	const third = limit.onIdle();

	t.not(first, second);
	t.not(second, third);

	await Promise.all([first, second, third]);

	t.true(ran);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle waiters resolve even if jobs reject', async t => {
	const limit = pLimit(1);

	const job = limit(async () => {
		await delay(10);
		throw new Error('boom');
	});
	job.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then

	const waiter = limit.onIdle();

	await t.notThrowsAsync(waiter);
});

